// js
// The engine admits the month's within-schedule overtime hours as ctx.entry.quantity.
const entry = get(ctx, 'entry', {});
const terms = ctx.subject.employment.terms;
const rate = get(terms, 'rate', {});
const amount = Number(get(rate, 'amount', 0));
const unit = get(rate, 'unit', 'MONTHLY');
const daily = Number(get(terms, 'normal_hours_per_day', 8));
const weekly = Number(
	get(terms, 'normal_hours_per_week', daily * Number(get(terms, 'normal_days_per_week', 5)))
);
const monthly = Number(get(terms, 'normal_hours_per_month', (weekly * 52) / 12));
let hourly = 0;
if (unit === 'HOURLY') hourly = amount;
else if (unit === 'DAILY') hourly = daily > 0 ? amount / daily : 0;
else hourly = monthly > 0 ? amount / monthly : 0;
const hours = Number(get(entry, 'quantity', 0));
return hours * hourly * ctx.lookup.multiplier;

